/// What importing a file WOULD do, worked out against this station and written nowhere.
///
/// The same code the import itself runs, so what this reports is what will happen rather than a second
/// opinion about it. It answers two questions an operator cannot get from the file alone: which
/// characters are new here and which would be rewritten, and what this station cannot honour about them
public struct PersonaImportPlan: Codable, Equatable, Sendable {
    /// What the file said it was. Reported rather than enforced: this repo edits migrations in place, so a version stamp cannot promise a shape, and the shapes are what was actually validated
    public var format: String
    /// The station it was taken from, when it said
    public var station: String?
    /// When it was taken, when it said
    public var takenAt: String?
    /// About the FILE rather than any one character in it
    public var notices: [PersonaImportNotice]
    public var personas: [PersonaImportEntry]

    public init(format: String, station: String? = nil, takenAt: String? = nil, notices: [PersonaImportNotice], personas: [PersonaImportEntry]) {
        self.format = format
        self.station = station
        self.takenAt = takenAt
        self.notices = notices
        self.personas = personas
    }

    private enum CodingKeys: String, CodingKey {
        case format = "format"
        case station = "station"
        case takenAt = "takenAt"
        case notices = "notices"
        case personas = "personas"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.format = try container.decode(String.self, forKey: .format)
        self.station = try container.decodeIfPresent(String.self, forKey: .station)
        self.takenAt = try container.decodeIfPresent(String.self, forKey: .takenAt)
        self.notices = try container.decode([PersonaImportNotice].self, forKey: .notices)
        self.personas = try container.decode([PersonaImportEntry].self, forKey: .personas)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.format, forKey: .format)
        try container.encodeIfPresent(self.station, forKey: .station)
        try container.encodeIfPresent(self.takenAt, forKey: .takenAt)
        try container.encode(self.notices, forKey: .notices)
        try container.encode(self.personas, forKey: .personas)
    }
}

