/// The same run with every break it has written so far, in order
public struct PersonaAudition: Codable, Equatable, Sendable {
    public var id: String
    public var personaId: String
    /// The character's own key, as `script_history` records it
    public var personaKey: String
    public var source: PersonaAuditionSource
    /// `cancelled` keeps whatever breaks were already written
    public var state: PersonaAuditionSummaryState
    /// How many breaks this run writes in total
    public var transitions: Int
    /// How many it has written so far, which is how far along it is
    public var written: Int
    /// Why writing it stopped, when it did
    public var error: String?
    /// ISO-8601
    public var cancelledAt: String?
    /// ISO-8601, whichever way the run ended
    public var finishedAt: String?
    /// ISO-8601
    public var createdAt: String
    public var breaks: [PersonaAuditionBreak]

    public init(id: String, personaId: String, personaKey: String, source: PersonaAuditionSource, state: PersonaAuditionSummaryState, transitions: Int, written: Int, error: String? = nil, cancelledAt: String? = nil, finishedAt: String? = nil, createdAt: String, breaks: [PersonaAuditionBreak]) {
        self.id = id
        self.personaId = personaId
        self.personaKey = personaKey
        self.source = source
        self.state = state
        self.transitions = transitions
        self.written = written
        self.error = error
        self.cancelledAt = cancelledAt
        self.finishedAt = finishedAt
        self.createdAt = createdAt
        self.breaks = breaks
    }

    private enum CodingKeys: String, CodingKey {
        case id = "id"
        case personaId = "personaId"
        case personaKey = "personaKey"
        case source = "source"
        case state = "state"
        case transitions = "transitions"
        case written = "written"
        case error = "error"
        case cancelledAt = "cancelledAt"
        case finishedAt = "finishedAt"
        case createdAt = "createdAt"
        case breaks = "breaks"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.id = try container.decode(String.self, forKey: .id)
        self.personaId = try container.decode(String.self, forKey: .personaId)
        self.personaKey = try container.decode(String.self, forKey: .personaKey)
        self.source = try container.decode(PersonaAuditionSource.self, forKey: .source)
        self.state = try container.decode(PersonaAuditionSummaryState.self, forKey: .state)
        self.transitions = try container.decode(Int.self, forKey: .transitions)
        self.written = try container.decode(Int.self, forKey: .written)
        self.error = try container.decodeIfPresent(String.self, forKey: .error)
        self.cancelledAt = try container.decodeIfPresent(String.self, forKey: .cancelledAt)
        self.finishedAt = try container.decodeIfPresent(String.self, forKey: .finishedAt)
        self.createdAt = try container.decode(String.self, forKey: .createdAt)
        self.breaks = try container.decode([PersonaAuditionBreak].self, forKey: .breaks)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.id, forKey: .id)
        try container.encode(self.personaId, forKey: .personaId)
        try container.encode(self.personaKey, forKey: .personaKey)
        try container.encode(self.source, forKey: .source)
        try container.encode(self.state, forKey: .state)
        try container.encode(self.transitions, forKey: .transitions)
        try container.encode(self.written, forKey: .written)
        try container.encodeIfPresent(self.error, forKey: .error)
        try container.encodeIfPresent(self.cancelledAt, forKey: .cancelledAt)
        try container.encodeIfPresent(self.finishedAt, forKey: .finishedAt)
        try container.encode(self.createdAt, forKey: .createdAt)
        try container.encode(self.breaks, forKey: .breaks)
    }
}

/// A character as a file: everything somebody would have to send to put this presenter on another
/// station, and nothing that belongs to the station it came from
public struct PersonaFile: Codable, Equatable, Sendable {
    /// What shape this is, so a file from a later build says so rather than being read wrongly. The shapes below are what an import actually validates; this is for the human reading the failure
    public var format: String
    /// When it was exported, ISO-8601
    public var takenAt: String
    /// The station it was taken from. Provenance only: an import writes into whichever station it is running as, and the two need not match
    public var station: String?
    public var personas: [PersonaFilePersona]

    public init(format: String, takenAt: String, station: String? = nil, personas: [PersonaFilePersona]) {
        self.format = format
        self.takenAt = takenAt
        self.station = station
        self.personas = personas
    }

    private enum CodingKeys: String, CodingKey {
        case format = "format"
        case takenAt = "takenAt"
        case station = "station"
        case personas = "personas"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.format = try container.decode(String.self, forKey: .format)
        self.takenAt = try container.decode(String.self, forKey: .takenAt)
        self.station = try container.decodeIfPresent(String.self, forKey: .station)
        self.personas = try container.decode([PersonaFilePersona].self, forKey: .personas)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.format, forKey: .format)
        try container.encode(self.takenAt, forKey: .takenAt)
        try container.encodeIfPresent(self.station, forKey: .station)
        try container.encode(self.personas, forKey: .personas)
    }
}

/// What importing actually did, with the plan it did it from.
///
/// All or nothing: a file whose import failed part-way leaves the station exactly as it was, on
/// `PUT /settings`' own rule. The preview is what stands between an operator and a surprise, so a
/// partial landing would be the one outcome nothing had described
public struct PersonaImportResult: Codable, Equatable, Sendable {
    /// What it decided to do, notices and all, so the answer carries its own explanation
    public var plan: PersonaImportPlan
    public var created: Int
    /// Characters whose sheet was rewritten. An update replaces the sheet and ADDS stories; it never deletes one the operator here wrote
    public var updated: Int
    public var storiesWritten: Int
    public var detailsWritten: Int
    /// The roster as it now stands, on this file's own rule: every mutation answers the whole list, because more than the named row can change
    public var personas: PersonaList

    public init(plan: PersonaImportPlan, created: Int, updated: Int, storiesWritten: Int, detailsWritten: Int, personas: PersonaList) {
        self.plan = plan
        self.created = created
        self.updated = updated
        self.storiesWritten = storiesWritten
        self.detailsWritten = detailsWritten
        self.personas = personas
    }

    private enum CodingKeys: String, CodingKey {
        case plan = "plan"
        case created = "created"
        case updated = "updated"
        case storiesWritten = "storiesWritten"
        case detailsWritten = "detailsWritten"
        case personas = "personas"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.plan = try container.decode(PersonaImportPlan.self, forKey: .plan)
        self.created = try container.decode(Int.self, forKey: .created)
        self.updated = try container.decode(Int.self, forKey: .updated)
        self.storiesWritten = try container.decode(Int.self, forKey: .storiesWritten)
        self.detailsWritten = try container.decode(Int.self, forKey: .detailsWritten)
        self.personas = try container.decode(PersonaList.self, forKey: .personas)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.plan, forKey: .plan)
        try container.encode(self.created, forKey: .created)
        try container.encode(self.updated, forKey: .updated)
        try container.encode(self.storiesWritten, forKey: .storiesWritten)
        try container.encode(self.detailsWritten, forKey: .detailsWritten)
        try container.encode(self.personas, forKey: .personas)
    }
}

